    if (record.geo) {
      assert.ok(Number.isFinite(record.geo.lat) && Number.isFinite(record.geo.lon), `${where}: geo point numeric`);
      assert.ok(Math.abs(record.geo.lat) <= 90 && Math.abs(record.geo.lon) <= 180, `${where}: geo point inside WGS84`);
    }
  }
});

