#!/usr/bin/env node
/**
 * Reproducible harvest of the Library of Congress Geography & Map Division's
 * pre-1800 map records through the documented loc.gov JSON API.
 *
 * Scope: every distinct map in the Library's own `subject:early works to 1800`
 * facet whose catalogue date lies in 1400–1799. This is a complete named
 * subject window, not a hand-picked showcase. Search results are inventory;
 * each item's own `rights` field is fetched before admission.
 *
 * Rights gate: only statements that affirmatively permit reuse are accepted —
 * the Geography & Map Division's "free to use and reuse unless a Rights
 * Advisory statement is present that indicates otherwise" statement with no
 * advisory, an explicit public-domain / no-known-copyright / U.S.-government
 * determination, or CC0/PDM. World Digital Library partner wording, rights
 * "not evaluated", "may be restricted", permission-required, all-rights-
 * reserved, non-commercial and copyright-undetermined statements are withheld.
 * The verbatim statement is kept on every record; nothing is relabelled PD.
 *
 * Usage:
 *   node scripts/harvest-loc.mjs                  # cached, writes public/data
 *   node scripts/harvest-loc.mjs --refresh        # re-fetch search pages
 *   node scripts/harvest-loc.mjs --refresh-rights # re-fetch item rights only
 *   node scripts/harvest-loc.mjs --no-write       # report only
 */
import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const value = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const OUT = resolve(value('out', resolve(ROOT, 'public/data')));
const CACHE = resolve(ROOT, '.cache/loc');
const REFRESH = has('refresh');
const REFRESH_RIGHTS = REFRESH || has('refresh-rights');
const WRITE = !has('no-write');
const CONCURRENCY = Math.max(1, Math.min(8, Number(value('concurrency', '6')) || 6));
const UA = 'maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; historical map catalogue)';
const API = 'https://www.loc.gov/maps/';
const FACET = 'subject:early works to 1800';
const DATE_WINDOW = '1400/1799';
const PAGE_SIZE = 100;
const RETRIEVED = '2026-10-20';
const MAX_BYTES = 24 * 1024 * 1024;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function fetchJson(url, { attempts = 4 } = {}) {
  let last;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const res = await fetch(url, {
        headers: { accept: 'application/json', 'user-agent': UA },
        signal: AbortSignal.timeout(60000),
      });
      if (res.ok) return { url, body: await res.json() };
      last = new Error(`HTTP ${res.status} ${url}`);
      if (res.status !== 429 && res.status < 500) break;
    } catch (error) {
      last = error;
    }
    await sleep(500 * attempt);
  }
  throw last;
}

function cachePath(...parts) {
  return resolve(CACHE, ...parts);
}

async function cachedJson(path, url, refresh) {
  if (!refresh) {
    try {
      return JSON.parse(await readFile(path, 'utf8'));
    } catch {}
  }
  const { body } = await fetchJson(url);
  await mkdir(dirname(path), { recursive: true });
  const temp = `${path}.tmp-${process.pid}`;
  await writeFile(temp, JSON.stringify(body));
  await rename(temp, path);
  return body;
}

function searchUrl(page) {
  const url = new URL(API);
  for (const [key, val] of Object.entries({
    fo: 'json',
    c: String(PAGE_SIZE),
    sp: String(page),
    fa: FACET,
    dates: DATE_WINDOW,
    at: 'results,pagination',
  }))
    url.searchParams.set(key, val);
  return url.href;
}

/** All four-digit years the catalogue states; never a depicted date. */
export function publicationYears(value) {
  const years = String(value ?? '')
    .match(/\b(?:1[0-9]{3}|20[0-9]{2})\b/g)
    ?.map(Number)
    .filter((year) => year >= 1400 && year <= 2100);
  if (!years?.length) return { start: null, end: null };
  return { start: Math.min(...years), end: Math.max(...years) };
}

const RESTRICTED =
  /rights advisory\s*:|rights status not evaluated|not been evaluated|may be restricted|permission (?:is )?required|prior written permission|all rights reserved|copyright undetermined|non[ -]?commercial|protected by copyright|contact (?:the )?(?:host|institution)/i;
const WDL = /world digital library|unaware of any copyright or other restrictions in the world digital library/i;
const GMD_FREE =
  /free to use and reuse unless a Rights Advisory statement is present that indicates otherwise/i;
const PUBLIC_DOMAIN =
  /in the public domain|no known copyright restrictions|not subject to copyright|u\.s\. government work|creativecommons\.org\/(?:publicdomain\/(?:mark|zero)\/1\.0|licenses\/by\/4\.0)/i;

function plain(value) {
  return String(value ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function rightsValue(payload) {
  return (
    payload['item.rights'] ??
    payload.item?.rights ??
    payload.rights ??
    []
  );
}

function advisoryValue(payload) {
  return (
    payload['item.rights_advisory'] ??
    payload.item?.rights_advisory ??
    payload.rights_advisory ??
    null
  );
}

function accessRestricted(payload) {
  return (
    payload['item.access_restricted'] ??
    payload.item?.access_restricted ??
    payload.access_restricted ??
    false
  ) === true;
}

/**
 * Return the affirmative reuse basis and verbatim statement, or null.
 * Exported so the gates can be regression-tested without network access.
 */
export function rightsBasisOf(payload) {
  const raw = rightsValue(payload);
  const advisory = advisoryValue(payload);
  const statement = plain(
    Array.isArray(raw) ? raw.map(plain).filter(Boolean).join(' ') : raw,
  );
  const advisoryText = plain(
    Array.isArray(advisory) ? advisory.map(plain).filter(Boolean).join(' ') : advisory,
  );
  if (!statement || accessRestricted(payload)) return null;
  if (WDL.test(statement) || WDL.test(advisoryText)) return null;
  if (advisoryText) return null;
  if (RESTRICTED.test(statement)) return null;
  if (GMD_FREE.test(statement)) {
    const first = statement
      .split(/(?<=\.)\s+(?=Credit Line:)/)[0]
      .replace(/^.*?The content of the Library of Congress Geography and Map Division digitized collections is /i, 'The content of the Library of Congress Geography and Map Division digitized collections is ');
    return { basis: 'gmd-free-to-use', statement: first };
  }
  if (PUBLIC_DOMAIN.test(statement))
    return { basis: 'public-domain', statement };
  return null;
}

/** IIIF image-service base for an item, preferring the tile.loc.gov service. */
export function imageServiceOf(document) {
  for (const candidate of document.image_url ?? []) {
    const url = String(candidate).split('#')[0];
    const match = url.match(
      /^(https:\/\/tile\.loc\.gov\/image-services\/iiif\/[^/]+(?:\/[^/]+)*?)\/full\//,
    );
    if (match) return match[1];
  }
  return null;
}

function firstSpecificCollection(partof) {
  const generic = new Set([
    'geography and map division',
    'catalog',
    'american memory',
    'world digital library',
  ]);
  return (partof ?? []).map(plain).find((name) => name && !generic.has(name.toLowerCase())) ?? '';
}

/** Build one bundled record. Returns null when the item fails a metadata gate. */
export function recordOf(document, rightsPayload) {
  const id = String(document.id ?? '').match(/\/item\/([^/]+)\/?$/)?.[1];
  if (!id || !/^[a-z0-9._-]+$/i.test(id)) return null;
  const formats = document.original_format ?? [];
  if (!formats.includes('map') || formats.includes('collection')) return null;
  if (document.access_restricted === true) return null;
  if (!document.digitized || !(document.image_url ?? []).length) return null;
  const rights = rightsBasisOf(rightsPayload);
  if (!rights) return null;
  const title = plain(document.title);
  if (!title) return null;
  const imageService = imageServiceOf(document);
  if (!imageService) return null;
  const { start, end } = publicationYears(document.date);
  const partof = (document.partof ?? []).map(plain).filter(Boolean);
  if (partof.includes('world digital library')) return null;
  const collection = firstSpecificCollection(partof);
  const place = [
    document.location_city?.[0],
    document.location_state?.[0],
    document.location_country?.[0],
  ]
    .map(plain)
    .filter(Boolean);
  const record = {
    id: `loc:${id}`,
    title,
    creators: (document.contributor ?? []).map(plain).filter(Boolean),
    providerId: 'loc',
    institution: partof.includes('geography and map division')
      ? 'Library of Congress, Geography and Map Division'
      : 'Library of Congress',
    rights: rights.statement,
    rightsBasis: rights.basis,
    rightsUrl: 'https://www.loc.gov/legal/',
    recordUrl: `https://www.loc.gov/item/${id}/`,
    viewerUrl: (document.resources ?? [])
      .map((entry) => plain(entry?.url))
      .find((url) => /^https:\/\/www\.loc\.gov\/resource\//.test(url)) ?? null,
    thumbnail: `${imageService}/full/304,/0/default.jpg`,
    imageService,
    type: 'map',
    collection: collection ? `${collection} — Library of Congress` : 'Library of Congress maps',
    sourceCollections: partof,
    languages: (document.language ?? []).map(plain).filter(Boolean),
    dateDisplay: plain(document.date),
    metadataSource: `https://www.loc.gov/item/${id}/?fo=json`,
  };
  if (place.length) record.subjectPlace = place.join(', ');
  if (start != null) {
    record.yearStart = start;
    record.yearEnd = end;
  }
  record.geoNote =
    'Library of Congress catalogue record. No verified map extent or alignment is stated here, so no geographic point is inferred.';
  for (const key of Object.keys(record)) {
    const val = record[key];
    if (key === 'creators') continue;
    if (val == null || val === '' || (Array.isArray(val) && val.length === 0)) delete record[key];
  }
  if (!Array.isArray(record.creators)) record.creators = [];
  return record;
}

async function pool(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  async function worker() {
    while (true) {
      const i = next++;
      if (i >= items.length) return;
      out[i] = await fn(items[i], i);
      await sleep(40);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

async function head(url, accept) {
  try {
    const res = await fetch(url, {
      headers: { accept, 'user-agent': UA, range: 'bytes=0-2047' },
      signal: AbortSignal.timeout(45000),
    });
    return { status: res.status, type: res.headers.get('content-type') };
  } catch (error) {
    return { status: 0, error: String(error.message) };
  }
}

async function verify(records) {
  const sample = [];
  const step = Math.max(1, Math.floor(records.length / 24));
  for (let i = 0; i < records.length && sample.length < 24; i += step) sample.push(records[i]);
  const results = await pool(sample, 4, async (record) => {
    const thumbnail = await head(record.thumbnail, 'image/jpeg');
    const info = await head(`${record.imageService}/info.json`, 'application/json');
    return {
      id: record.id,
      thumbnail: thumbnail.status,
      info: info.status,
      thumbnailType: thumbnail.type,
      infoType: info.type,
    };
  });
  return {
    retrieved: RETRIEVED,
    sample: results.length,
    thumbnailOk: results.filter((r) => (r.thumbnail === 200 || r.thumbnail === 206) && /image\//.test(r.thumbnailType ?? '')).length,
    imageInfoOk: results.filter((r) => r.info === 200 && /json/.test(r.infoType ?? '')).length,
    examples: results.slice(0, 5),
  };
}

async function main() {
  const first = await cachedJson(
    cachePath('search', 'page-1.json'),
    searchUrl(1),
    REFRESH,
  );
  const total = first.pagination?.of ?? null;
  const pages = total ? Math.ceil(total / PAGE_SIZE) : 1;
  console.log(`LoC inventory: ${total ?? '?'} records in ${pages} pages (${FACET}, ${DATE_WINDOW})`);
  const documents = [...(first.results ?? [])];
  let next = 2;
  async function searchWorker() {
    while (true) {
      const page = next++;
      if (page > pages) return;
      const body = await cachedJson(
        cachePath('search', `page-${page}.json`),
        searchUrl(page),
        REFRESH,
      );
      documents.push(...(body.results ?? []));
      if (page % 10 === 0) console.log(`cached search page ${page}/${pages}`);
      await sleep(100);
    }
  }
  await Promise.all(Array.from({ length: 3 }, searchWorker));

  const seen = new Set();
  const candidates = [];
  const rejected = {};
  for (const document of documents) {
    const id = String(document.id ?? '').match(/\/item\/([^/]+)\/?$/)?.[1];
    if (!id || seen.has(id)) continue;
    seen.add(id);
    if ((document.partof ?? []).includes('world digital library')) {
      rejected['World Digital Library partner content (separate rights)'] =
        (rejected['World Digital Library partner content (separate rights)'] || 0) + 1;
      continue;
    }
    if (!document.digitized || !(document.image_url ?? []).length) {
      rejected['not digitized / no image'] = (rejected['not digitized / no image'] || 0) + 1;
      continue;
    }
    if (!(document.original_format ?? []).includes('map') || (document.original_format ?? []).includes('collection')) {
      rejected['not a single cartographic resource'] = (rejected['not a single cartographic resource'] || 0) + 1;
      continue;
    }
    if (!imageServiceOf(document)) {
      rejected['no tile.loc.gov IIIF image service'] = (rejected['no tile.loc.gov IIIF image service'] || 0) + 1;
      continue;
    }
    candidates.push(document);
  }
  console.log(`Unique search results: ${seen.size}; metadata-eligible: ${candidates.length}`);

  const rights = await pool(candidates, CONCURRENCY, async (document) => {
    const id = document.id.match(/\/item\/([^/]+)\/?$/)[1];
    const url = `https://www.loc.gov/item/${id}/?fo=json&at=item.rights,item.rights_advisory,item.access_restricted`;
    try {
      const payload = await cachedJson(
        cachePath('rights', `${id}.json`),
