    retrieved: RETRIEVED,
    records: [...recordsDoc.records, ...added],
    method: `${recordsDoc.method ? recordsDoc.method + ' ' : ''}Library of Congress pre-1800 Geography and Map Division records are imported through the documented loc.gov JSON API (subject:early works to 1800, dates 1400/1799) with per-item rights confirmation.`,
  };
  combined.selection ??= {};
  combined.selection['loc:early-works-1800'] = {
