    query: { fa: FACET, dates: DATE_WINDOW, pageSize: PAGE_SIZE },
    totalReported: total,
    pagesRead: pages,
    uniqueResults: seen.size,
    metadataEligible: candidates.length,
    rightsChecked: rights.filter((entry) => !entry.error).length,
    rightsErrors: errors.length,
    alreadyPresent: records.length - added.length,
    added: added.length,
    rightsBasis: bases,
    withheld: rejected,
    rule:
      'Every distinct map in the Library of Congress Maps subject facet "early works to 1800" with a catalogue date in 1400–1799, digitized with a tile.loc.gov IIIF image service, whose own item record carries an affirmative reuse statement (Geography & Map Division free-to-use with no Rights Advisory, explicit public domain / no known copyright / U.S. government / CC0/PDM). World Digital Library partner items, rights "not evaluated", restricted, permission-required, all-rights-reserved, non-commercial and copyright-undetermined items stay out. Dates are the catalogue publication date; no depicted date, extent or alignment is inferred.',
