  const bytes = Buffer.byteLength(JSON.stringify(combined));
  console.log(`Catalogue would be ${combined.records.length} records, ${(bytes / 1024 / 1024).toFixed(2)} MiB`);
  if (bytes > MAX_BYTES) throw new Error('Catalogue exceeds 24 MiB; shard before writing.');
  if (!WRITE) return;

  const provider = {
