      imageInfo: 'https://tile.loc.gov/image-services/iiif/{service}/info.json',
      thumbnail: 'https://tile.loc.gov/image-services/iiif/{service}/full/304,/0/default.jpg',
      documentation: 'https://www.loc.gov/apis/',
