    },
    apiHosts: ['www.loc.gov', 'tile.loc.gov'],
    method:
      'Documented loc.gov JSON search (subject:early works to 1800, dates 1400/1799, 100 results per page, all pagination pages) with a per-item rights request before admission. No hand-picked titles, decade cap or geographic quota; titles, dates, creators, languages and collection names are the catalogue’s own values.',
    collections: [
      {
